package app.quanneng;
import android.app.Activity;
import android.media.AudioManager;
import android.view.*;
import android.view.accessibility.AccessibilityManager;
/** 单层手势识别，拖动松手才定位，长按释放恢复速度。 */
final class PlayerGestures implements View.OnTouchListener {
 interface Target {boolean ready();int position();int duration();void seek(int ms);void toggle();void tap();void feedback(String value);float speed();void speed(float value);}
 private final Activity a;private final Target t;private final GestureDetector detector;private final AudioManager audio;private float x,y,brightness,oldSpeed;private int pos,volume,axis;private boolean held,moved;
 PlayerGestures(Activity activity,Target target){a=activity;t=target;audio=(AudioManager)a.getSystemService(Activity.AUDIO_SERVICE);detector=new GestureDetector(a,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(MotionEvent e){return true;}public boolean onSingleTapUp(MotionEvent e){t.tap();return true;}public boolean onDoubleTap(MotionEvent e){if(t.ready()){float fraction=e.getX()/Math.max(1,width);if(fraction<.35f)t.seek(Math.max(0,t.position()-10000));else if(fraction>.65f)t.seek(Math.min(t.duration(),t.position()+10000));else t.toggle();}return true;}public void onLongPress(MotionEvent e){if(t.ready()&&!moved){held=true;oldSpeed=t.speed();t.speed(2);t.feedback("临时 2 倍速 · 松手恢复");}}});}
 private int width,height;
 @Override public boolean onTouch(View v,MotionEvent e){AccessibilityManager access=(AccessibilityManager)a.getSystemService(Activity.ACCESSIBILITY_SERVICE);boolean enabled=a.getSharedPreferences("player-gestures",0).getBoolean("enabled",true)&&(access==null||!access.isTouchExplorationEnabled());if(!enabled)return false;width=v.getWidth();height=v.getHeight();int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();pos=t.position();volume=audio.getStreamVolume(AudioManager.STREAM_MUSIC);brightness=a.getWindow().getAttributes().screenBrightness;if(brightness<0)brightness=.5f;axis=0;moved=false;held=false;}
  detector.onTouchEvent(e);if(action==MotionEvent.ACTION_MOVE&&t.ready()&&!held){float dx=e.getX()-x,dy=e.getY()-y;if(axis==0&&Math.max(Math.abs(dx),Math.abs(dy))>24*a.getResources().getDisplayMetrics().density){axis=Math.abs(dx)>Math.abs(dy)?1:2;moved=true;}if(axis==1){int target=(int)Math.max(0,Math.min(t.duration(),pos+dx/Math.max(1,width)*120000));t.feedback("松手定位 · "+SubtitleStore.stamp(target));}else if(axis==2){if(x<width/2f){WindowManager.LayoutParams p=a.getWindow().getAttributes();p.screenBrightness=Math.max(.03f,Math.min(1,brightness-dy/Math.max(1,height)));a.getWindow().setAttributes(p);t.feedback("亮度 "+Math.round(p.screenBrightness*100)+"%");}else{int max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);int next=Math.max(0,Math.min(max,Math.round(volume-dy/Math.max(1,height)*max)));try{audio.setStreamVolume(AudioManager.STREAM_MUSIC,next,0);t.feedback("音量 "+Math.round(next*100f/Math.max(1,max))+"%");}catch(SecurityException ignored){t.feedback("请使用系统音量键调整");}}}}
  if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){if(held){t.speed(oldSpeed);held=false;}if(action==MotionEvent.ACTION_UP&&axis==1&&t.ready())t.seek((int)Math.max(0,Math.min(t.duration(),pos+(e.getX()-x)/Math.max(1,width)*120000)));axis=0;}return true;
 }
}
